parameters.jsCode:
// Normalize the webhook payload and preserve the proposal across approval callbacks.
const webhook = $node['Webhook: Receive RFP'].json;
const clientData = webhook.body ?? webhook;
const proposalContent = $node['OpenAI: Generate Proposal'].json.text;

if (!clientData.client_name || !clientData.client_email) {
  throw new Error('client_name and client_email are required');
}
if (!proposalContent) {
  throw new Error('The AI node returned an empty proposal');
}

return [{
  json: {
    client_name: clientData.client_name,
    client_email: clientData.client_email,
    proposal_markdown: proposalContent,
    generated_at: new Date().toISOString(),
    rfp_id: clientData.rfp_id || `RFP-${Date.now()}`
  }
}];

// Convert the Markdown draft into safe, printable HTML without executing embedded HTML.
const proposal = $node['Code: Format Proposal'].json;
const escapeHtml = (value) => String(value)
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const escaped = escapeHtml(proposal.proposal_markdown);
const formatted = escaped
  .replace(/^### (.+)$/gm, '<h3>$1</h3>')
  .replace(/^## (.+)$/gm, '<h2>$1</h2>')
  .replace(/^# (.+)$/gm, '<h1>$1</h1>')
  .replace(/^[-*] (.+)$/gm, '<li>$1</li>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\n/g, '<br>');

const pdfHtml = `<!doctype html><html><head><meta charset="utf-8"><style>
body{font-family:Arial,sans-serif;color:#172033;line-height:1.55;margin:42px}
h1,h2,h3{color:#3157d5;margin-top:24px}li{margin-left:18px}
.meta{color:#65708a;font-size:12px;border-bottom:1px solid #dfe5f2;padding-bottom:12px}
</style></head><body><div class="meta">RFP ${escapeHtml(proposal.rfp_id)} · Generated ${escapeHtml(proposal.generated_at)}</div>${formatted}</body></html>`;

return [{ json: { ...proposal, pdf_html: pdfHtml } }];
